        <h1 class="title-wrap">
          <span class="qualified-channel-title ellipsized has-badge"><span class="qualified-channel-title-wrapper"><span dir="ltr" class="qualified-channel-title-text g-hovercard" data-ytid="UC6xBhF4QYIPPF2_-ExZzd2w" data-name="gb_ch_rec"             ><a dir="ltr" href="/user/FUNKER530" class=" yt-uix-sessionlink" title="FUNKER530 - Veteran Community &amp; Combat Footage" data-sessionlink="feature=gb_ch_rec&amp;ei=oVLWU-iSGILaqAWR0YCACw"      >FUNKER530 - Veteran Community &amp; Combat Footage</a></span></span><a class="qualified-channel-title-badge" href="//support.google.com/youtube/bin/answer.py?answer=3046484&amp;hl=en" target="_blank"><img src="http://s.ytimg.com/yts/img/pixel-vfl3z5WfW.gif" class="yt-channel-title-icon-verified yt-uix-tooltip yt-sprite" alt="" data-tooltip-text="Verified"></a></span>
        </h1>
      </div>
      <p class="description">
        I feel extremely blessed to have been given the privilege of reaching so many, so easily through YouTube and Facebook. I feel that it is my responsibility to expand the capabilities of FUNKER530 in 2014, in ways that more directly help a larger amount of veterans.

Profits from FUNKER530 are donated regularly to veteran related charities, our community provides a platform for veterans looking to share their experiences, and it broadcasts the Military Minds&#39; videos which give veterans dealing with PTSD an outlet to share, and let others know they aren&#39;t alone. 

In 2013 we have taken it a step further and have begun working with Homes For Our Troops who builds homes for our severely injured combat veterans. I know this community will help this amazing organization grow and get our veterans the help they deserve. 

- Funker

This channel is in no way affiliated with any Government, DND or DoD. Videos and links on this channel hold no official endorsement.
      </p>
